def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full solid lines are the separators; preserve their colors.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def bands(size, separators):
        result = []
        start = 0
        for s in separators:
            if start < s:
                result.append((start, s))
            start = s + 1
        if start < size:
            result.append((start, size))
        return result

    rb = bands(h, sep_rows)
    cb = bands(w, sep_cols)
    if len(rb) < 2 or len(cb) < 2:
        return grid

    # Identify a panel containing the motif, represented in panel-local coordinates.
    template = None
    for r0, r1 in rb:
        for c0, c1 in cb:
            cells = [(r-r0, c-c0, grid[r][c])
                     for r in range(r0, r1)
                     for c in range(c0, c1)
                     if grid[r][c] != 7]
            if cells:
                template = cells
                break
        if template is not None:
            break

    if template is None:
        return grid

    out = [row[:] for row in grid]
    for r0, r1 in rb:
        for c0, c1 in cb:
            for dr, dc, color in template:
                if r0 + dr < r1 and c0 + dc < c1:
                    out[r0 + dr][c0 + dc] = color
    return out
